 3	const SIGNIFICANT_DIGITS: usize = 6;
 4	
 5	pub fn format_rgb(rgb: RGB) -> String {
 6	    format!(
 7	        "{} {} {}",
 8	        format_cpp_float(rgb.r),
 9	        format_cpp_float(rgb.g),
10	        format_cpp_float(rgb.b)
11	    )
12	}
13	
14	pub fn format_cpp_float(value: f32) -> String {
15	    if value.is_nan() {
16	        return if value.is_sign_negative() {
17	            String::from("-nan")
18	        } else {
19	            String::from("nan")
20	        };
21	    }
22	
23	    if value.is_infinite() {
24	        return if value.is_sign_negative() {
25	            String::from("-inf")
26	        } else {
27	            String::from("inf")
28	        };
29	    }
30	
31	    if value == 0.0 {
32	        return if value.is_sign_negative() {
33	            String::from("-0")
34	        } else {
35	            String::from("0")
36	        };
37	    }
38	
39	    let scientific = format!("{:.*e}", SIGNIFICANT_DIGITS - 1, value);
40	    let (mantissa, exponent) = split_scientific(&scientific);
41	
42	    if exponent < -4 || exponent >= SIGNIFICANT_DIGITS as i32 {
43	        return format!(
44	            "{}e{:+03}",
45	            trim_fractional_zeros(mantissa.to_string()),
46	            exponent
47	        );
48	    }
49	
50	    let digits_after_decimal = (SIGNIFICANT_DIGITS as i32 - exponent - 1) as usize;
51	    trim_fractional_zeros(format!("{:.*}", digits_after_decimal, value))
52	}
53	
54	fn split_scientific(text: &str) -> (&str, i32) {
55	    let (mantissa, exponent) = text.split_once('e').unwrap();
56	    (mantissa, exponent.parse::<i32>().unwrap())
57	}
58	
59	fn trim_fractional_zeros(mut text: String) -> String {
60	    if text.contains('.') {
61	        while text.ends_with('0') {
62	            text.pop();
63	        }
64	        if text.ends_with('.') {
65	            text.pop();
66	        }
67	    }
68	
69	    text
70	}
